/**
 * The `type/subtype` of a valid media type, or `undefined` when the header
 * value is missing or could not be parsed. An invalid value has no media
 * type to report, so it must not be exposed as the meaningless `'/'`.
 * @returns {string | undefined}
 */
get mediaType () {
  return this.#valid === true
    ? `${this.#type}/${this.#subtype}`
    : undefined
}

