      cb(err)
    }
  })

  const response = new Writable()
  Object.assign(response, {
    setHeader: () => { },
    hasHeader: () => false,
    getHeader: () => undefined,
    writeHead: () => { },
    write: () => { },
    headersSent: true
  })

  const log = {
    warn: () => { }
  }

  const fakeRequest = {
    [kRouteContext]: {
      onSend: null,
      server: { [kLogController]: new LogController() }
    }
  }

  const reply = new Reply(response, fakeRequest, log)
  reply.send(payload)
  payload.destroy(new Error('stream error'))

  t.assert.strictEqual(destroyCalled, true, 'Error not logged and not streamed')
})

